INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63873123', 63873123, 'analyze_legacy', 'Kota Malang', 'kabkota', 'Bagian Umum', 'Belanja Alat/Bahan untuk Kegiatan Kantor-Perabot Kantor', 'Barang', 'E-Purchasing', 'Jawa Timur, Malang (Kota)', 159656000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Pengadaan alat dan bahan pembersih kantor yang digunakan untuk menunjang kebersihan, kerapian, dan kenyamanan lingkungan kerja sehari-hari. Pengadaan ini meliputi penyediaan berbagai jenis alat kebersihan dan bahan habis pakai yang dibutuhkan untuk pemeliharaan ruang kerja, ruang pelayanan, ruang rapat, toilet, dan area pendukung lainnya, agar tetap memenuhi standar kebersihan dan kesehatan kerja. Ruang lingkup pekerjaan meliputi pengadaan alat pembersih, antara lain sapu, pel lantai, ember, kain pel, sikat, tempat sampah, dan perlengkapan kebersihan lainnya, serta pengadaan bahan pembersih antara lain cairan pembersih lantai, pembersih kaca, pembersih toilet, deterjen, sabun pembersih, pengharum ruangan, dan bahan sejenis.', '1. Seluruh barang yang disediakan harus baru, belum pernah digunakan, dan bukan barang rekondisi 2. Barang sesuai dengan fungsi dan peruntukannya sebagai alat dan bahan pembersih kantor 3. Bahan pembersih memiliki masa kedaluwarsa yang masih berlaku pada saat penyerahan 4. Barang aman digunakan di lingkungan perkantoran dan tidak mengandung bahan berbahaya yang dilarang 5. Kemasan barang utuh, rapi, dan berlabel jelas', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1211133);
