INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63894526', 63894526, 'analyze_legacy', 'Kota Malang', 'kabkota', 'Dinas Pendidikan dan Kebudayaan', 'Belanja Modal Alat Kantor Lainnya - Finger Print - SDN Dinoyo 4', 'Barang', 'E-Purchasing', 'Jawa Timur, Malang (Kota)', 7037300, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Modal Alat Kantor Lainnya berupa pengadaan mesin presensi sidik jari (finger print) yang digunakan untuk mendukung pencatatan kehadiran pegawai secara elektronik, akurat, dan terintegrasi. Paket pekerjaan ini meliputi pengadaan unit mesin finger print sesuai spesifikasi teknis yang ditetapkan, instalasi perangkat, pengaturan awal sistem presensi, serta pengujian fungsi agar dapat digunakan secara optimal. Pengadaan ini bertujuan meningkatkan disiplin, akuntabilitas, dan tertib administrasi kehadiran pegawai dalam pelaksanaan tugas dan kegiatan operasional.', 'Pengadaan mesin presensi sidik jari (finger print) untuk pencatatan kehadiran pegawai secara elektronik, dengan kapasitas minimal 1.000 pengguna, dilengkapi layar tampilan, konektivitas USB/LAN, perangkat lunak pendukung, garansi resmi, serta instalasi dan uji fungsi hingga siap digunakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1213251);
