INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63877368', 63877368, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Direktorat Jenderal Tata Ruang', 'Fasilitasi Penyelarasan Kebijakan Nasional pada Pulau Jawa, Pulau Bali, dan Kepulauan Nusa Tenggara', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 240185000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1', 'Kawasan Strategis Nasional (KSN) adalah wilayah yang penataan ruangnya diprioritaskan karena mempunyai pengaruh sangat penting secara nasional terhadap kedaulatan negara, pertahanan dan keamanan negara, ekonomi, sosial, budaya, dan/atau lingkungan, termasuk wilayah yang telah ditetapkan sebagai warisan dunia. Penataan ruang KSN dilakukan untuk mengembangkan, melestarikan, melindungi dan/atau mengkoordinasikan keterpaduan pembangunan nilai strategis kawasan dalam mendukung penataan ruang wilayah. Dalam Pasal 14 Undang-Undang Nomor 26 Tahun 2007 tentang Penataan Ruang, dinyatakan bahwa RTR Pulau/Kepulauan dan KSN merupakan rencana rinci yang disusun sebagai perangkat operasional dari rencana umum tata ruang pada sistem nasional. Selanjutnya PP Nomor 13 Tahun 2017 tentang Perubahan Atas PP Nomor 26 Tahun 2008 tentang RTRWN menetapkan 76 (tujuh puluh enam) KSN. Rencana Tata Ruang Pulau Jawa-Bali telah ditetapkan melalui Peraturan Presiden Nomor 72 Tahun 2023 tentang tentang Rencana Tata Ruang Pulau Jawa-Bali dan Rencana Tata Ruang Kepulauan Nusa Tenggara telah ditetapkan melalui Peraturan Presiden (Perpres) Nomor 56 Tahun 2014 tentang Rencana Tata Ruang Kepulauan Nusa Tenggara. Terdapat beberapa kawasan strategis nasional yang telah ditetapkan di kawasan Pulau Jawa, Pulau Bali dan Kepulauan Nusa Tenggara, diantaranya adalah Kawasan Perkotaan Cekungan Bandung, Kawasan Perkotaan Kedung Sepur, Kawasan Perkotaan Gerbangkertosusila, dan Kawasan Subak-Bali Landscape merupakan kawasan strategis nasional yang ditetapkan dengan diundangkannya PP Nomor 13 Tahun 2017 tentang Perubahan Atas PP Nomor 26 Tahun 2008 tentang Rencana Tata Ruang Wilayah Nasional. Keterlibatan masyarakat dalam proses diseminasi dan penyelarasan kebijakan nasional akan mendorong partisipasi aktif, sehingga menciptakan sinergi antara kebijakan pemerintah dan aspirasi lokal baik untuk kebijakan tata ruang maupun kebijakan sektor lainnya serta dapat mendukung pencapaian tujuan pembangunan nasional yang berkelanjutan. Dalam rangka meningkatkan kesadaran masyarakat tentang pentingnya tata ruang dengan memahami rencana tata ruang serta penyelarasan kebijakan nasional (fasilitasi dan koordinasi penyiapan rekomendasi solusi isu pemanfaatan ruang yang ada dalam KSN) kepada stakeholder terkait baik di lingkup Pemerintah Pusat maupun pemerintah daerah, maka pada tahun anggaran 2026 Direktorat Perencanaan Tata Ruang-Direktorat Jenderal Tata Ruang, Kementerian Agraria dan Tata Ruang akan melaksanakan Fasilitasi Penyelarasan Kebijakan Nasional Pada Pulau Jawa, Pulau Bali dan Kepulauan Nusa Tenggara.', 'Keluaran kegiatan ini mencakup: Dokumen inventarisasi konflik dan rekomendasi solusi di dalam KSN pada Pulau Jawa, Pulau Bali dan Kepulauan Nusa Tenggara; Dokumen Diseminasi RTR Nasional pada Pulau Jawa, Pulau Bali dan Kepulauan Nusa Tenggara.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1218528);
