INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63897783', 63897783, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Direktorat Jenderal Tata Ruang', 'Penyelesaian NSPK Perencanaan Tata Ruang', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 515267000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '1', 'Berdasarkan Undang - Undang Nomor 26 Tahun 2007 tentang Penataan Ruang (UU 26/2007), Pasal 8 Ayat 5, disebutkan bahwa dalam rangka penyelenggaraan penataan ruang, Pemerintah berwenang menyusun dan menetapkan pedoman bidang penataan ruang. Pedoman bidang penataan ruang yang dimaksud mencakup norma, standar, dan manual dalam bidang penataan ruang. Sesuai Peraturan Pemerintah Nomor 21 Tahun 2021 tentang Penyelenggaraan Penataan Ruang pasal 3 disebutkan bahwa pengaturan penataan ruang dilakukan melalui penyusunan dan penetapan pedoman yang memuat norma, standar, prosedur, dan kriteria bidang Penataan Ruang. Norma, Standar, Prosedur, dan Kriteria (NSPK) memuat hal-hal yang akan diatur, persyaratan, tata cara, mekanisme kriteria, pengelolaan, dan sebagainya. Pasca diterbitkannya UU Cipta Kerja dan PP Penyelenggaraan Penataan Ruang membutuhkan peraturan turunan sebagai peraturan pelaksana yang memberikan muatan yang bersifat lebih teknis dan implementatif. Peraturan Pelaksana dapat berupa revisi dari Peraturan Menteri yang telah disusun dan/atau Petunjuk Teknis yang memerlukan tahap penyelesaian untuk dilakukan legalisasi agar menjadi acuan dan berkekuatan hukum bagi pelaksanaan kegiatan oleh pemerintah, pemerintah daerah, masyarakat serta pemangku kepentingan terkait. Dalam implementasi atau penerapan Peraturan Menteri dan/atau Petujuk Teknis yang dilakukan oleh pemerintah, pemerintah daerah, dan masyarakat, perlu dilakukan uji publik, penyempurnaan, penyepakatan dan harmonisasi terhadap muatan teknis rancangan peraturan menteri dan petunjuk teknis yang telah disusun sebelum dilakukan pengesahan menjadi peraturan perundang-undangan. Berdasarkan Peraturan Menteri Agraria dan Tata Ruang (ATR)/Kepala Badan Pertanahan Nasional (BPN) Nomor 6 Tahun 2025 tentang Organisasi dan Tata Kerja Kementerian ATR/BPN, Direktorat Jenderal Tata Ruang menyelenggarakan fungsi penyusunan NSPK di bidang perencanaan tata ruang nasional, pembinaan perencanaan tata ruang daerah, dan sinkronisasi pemanfaatan ruang. Untuk menjawab kebutuhan di atas, serta untuk menyediakan peraturan yang mampu mendukung berbagai dinamika pembangunan, maka Direktorat Jenderal Tata Ruang c.q. Direktorat Perencanaan Tata Ruang pada tahun anggaran 2026 ini memandang penting untuk melaksanakan pekerjaan Penyelesaian NSPK Bidang Tata Ruang tetang Pedoman Pemanfaatan Sempadan Pantai dan Pedoman Integrasi Rencana Zonasi Wilayah Pesisir dan Pulau-Pulau Kecil (RZWP3K) ke dalam Rencana Tata Ruang Wilayah (RTRW) Provinsi dalam rangka melengkapi dan menyempurnakan kebijakan/peraturan yang telah disusun untuk menjadi acuan legal bagi pelaksanaan kegiatan bidang tata ruang oleh pemerintah, pemerintah daerah, masyarakat dan pemangku kepentingan terkait.', 'Keluaran dalam pekerjaan ini adalah sebagai berikut: Rancangan peraturan perundang-undangan (siap harmonisasi dan/atau telah harmonisasi); dan Bahan sosialisasi peraturan perundang-undangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1218613);
